def rotate_90(grid):
    return [list(r) for r in zip(*grid[::-1])]

def rotate_180(grid):
    return rotate_90(rotate_90(grid))

def rotate_270(grid):
    return rotate_90(rotate_180(grid))

rot90 = rotate_90(rows)
rot180 = rotate_180(rows)
rot270 = rotate_270(rows)

print(f"Rot90 equals original: {rows == rot90}")
print(f"Rot180 equals original: {rows == rot180}")
print(f"Rot270 equals original: {rows == rot270}")

