print("\n--- Zero region ---")
min_r, max_r = h, 0
min_c, max_c = w, 0
for i in range(h):
    for j in range(w):
        if rows[i][j] == 0:
            min_r = min(min_r, i)
            max_r = max(max_r, i)
            min_c = min(min_c, j)
